python3 -I -c "import os,json,hashlib; from pathlib import Path; import xml.etree.ElementTree as E; root=Path(os.environ['LABVIEW_ENVIRONMENT'])/'actor-framework'; out=Path('benchmark/challenge-sources'); out.mkdir(exist_ok=True); names=['library-icon-tests','library-specialty'];
for name in names:
 c=json.loads((Path('benchmark/cases/dev')/(name+'.json')).read_text()); a=c['artifact']; raw=(root/a['path']).read_bytes(); assert hashlib.sha256(raw).hexdigest()==a['sha256']; target=out/(name+'.lvlib'); assert not target.exists() or target.read_bytes()==raw; target.write_bytes(raw); xml=E.fromstring(raw); print(json.dumps({'case':name,'preserved':str(target),'bytes':len(raw),'sha256':a['sha256'],'root':xml.attrib,'properties':[{'index':i,'attributes':p.attrib,'text':p.text} for i,p in enumerate(xml.findall('Property'),1)],'items':[p.attrib for p in xml.findall('Item')]},ensure_ascii=False))
p=Path('.session/report.md'); p.write_text(p.read_text()+'\nPreserved the two small original library XML files under benchmark/challenge-sources after checking their case-pinned SHA256 values; these support offline generation and substantive locator review.\n')"

